import bpy,json,sys,pathlib
s=bpy.context.scene
settings={'frame':s.frame_current,'blender':bpy.app.version_string,'engine':s.render.engine,'cycles':{k:getattr(s.cycles,k) for k in ['samples','seed','use_denoising','use_adaptive_sampling','adaptive_threshold','adaptive_min_samples','sample_clamp_direct','sample_clamp_indirect','blur_glossy','pixel_filter_type','filter_width','use_animated_seed']},'display':{k:getattr(s.view_settings,k) for k in ['view_transform','look','exposure','gamma']},'render':{k:getattr(s.render,k) for k in ['resolution_x','resolution_y','resolution_percentage','dither_intensity','film_transparent']},'camera':{'name':s.camera.name,'type':s.camera.data.type,'location':list(s.camera.location),'ortho_scale':s.camera.data.ortho_scale},'lights':[{'name':o.name,'type':o.data.type,'energy':o.data.energy,'location':list(o.location),'rotation':list(o.rotation_euler)} for o in s.objects if o.type=='LIGHT'],'worldStrength':s.world.node_tree.nodes.get('Background').inputs[1].default_value,'albedoTargetMaterials':sorted(m.name for m in bpy.data.materials if m.use_nodes and m.node_tree.nodes.get('Principled BSDF')),'world':[(n.name,n.type) for n in s.world.node_tree.nodes]}
pathlib.Path(sys.argv[sys.argv.index('--')+1]).write_text(json.dumps(settings,indent=2))
